>>>>> @@ -4231,6 +4244,8 @@ void f2fs_build_gc_manager(struct f2fs_sb_info *sbi);
>>>>>    int f2fs_gc_range(struct f2fs_sb_info *sbi,
>>>>>                unsigned int start_seg, unsigned int end_seg,
>>>>>                bool dry_run, unsigned int dry_run_sections);
