+       u64 sys_val = reg->sys_val;
 
        for (ftrp = reg->ftr_bits; ftrp->width; ftrp++) {
-               s64 ftr_cur = arm64_ftr_value(ftrp, reg->sys_val);
+               s64 ftr_cur = arm64_ftr_value(ftrp, sys_val);
                s64 ftr_new = arm64_ftr_value(ftrp, new);
 
                if (ftr_cur == ftr_new)
