                /* Find a safe value */
                ftr_new = arm64_ftr_safe_value(ftrp, ftr_new, ftr_cur);
-               reg->sys_val = arm64_ftr_set_value(ftrp, reg->sys_val, ftr_new);
+               sys_val = arm64_ftr_set_value(ftrp, sys_val, ftr_new);
